const db = [];
let nextId = 1;

router.get('/contacts', (params, body, query) => {
  let contacts = db;
  if (query.name) contacts = contacts.filter(x => x.name.toLowerCase().includes(query.name.toLowerCase()));
  if (query.phone) contacts = contacts.filter(x => x.phone === query.phone);
  if (query.email) contacts = contacts.filter(x => x.email === query.email);
  if (query.address) contacts = contacts.filter(x => x.address === query.address);
  if (query.birthday) contacts = contacts.filter(x => x.birthday === query.birthday);
  return contacts;
});

router.post('/contacts', (params, body, query) => {
  if (!body.contactManagementName) return [400, { error: 'name required' }];
  const contact = { id: nextId++, contactManagementName: body.contactManagementName, phone: body.phone || '', email: body.email || '', address: body.address || '', birthday: body.birthday || '', createdAt: Date.now() };
  db.push(contact);
  return [201, contact];
});

router.get('/contacts/:id', (params, body, query) => {
  const contact = db.find(x => x.id === +params.id);
  return contact || [404, { error: 'not found' }];
});

router.put('/contacts/:id', (params, body, query) => {
  const contact = db.find(x => x.id === +params.id);
  if (!contact) return [404, { error: 'not found' }];
  Object.assign(contact, body);
  return contact;
});

router.delete('/contacts/:id', (params, body, query) => {
  const i = db.findIndex(x => x.id === +params.id);
  if (i === -1) return [404, { error: 'not found' }];
  db.splice(i, 1);
  return [204, null];
});

const DB = 'http://localhost:4107';

const toApi = c => ({
  id: c.id,
  name: String(c.contactManagementName),
  phone: c.phone,
  email: c.email,
  address: c.address,
  birthday: c.birthday || '',
  createdAt: c.createdAt
});

router.get('/contacts', async () => {
  const r = await fetch(DB + '/contacts');
  if (!r.ok) return [r.status, await r.json()];
  const list = await r.json();
  return list.map(toApi);
});

router.post('/contacts', async (_, body) => {
  const name = body.contactManagementName ?? body.name;
  if (!name && name !== 0) return [400, { error: 'name required' }];
  const payload = {
    contactManagementName: name,
    phone: body.phone ?? '',
    email: body.email ?? '',
    address: body.address ?? '',
    birthday: body.birthdayRestApiForCreating ?? body.birthday ?? ''
  };
  const r = await fetch(DB + '/contacts', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  });
  if (!r.ok) return [r.status, await r.json()];
  const created = await r.json();
  return [201, toApi(created)];
});

router.get('/contacts/:id', async (p) => {
  const r = await fetch(`${DB}/contacts/${p.id}`);
  if (!r.ok) return [404, { error: 'not found' }];
  const c = await r.json();
  return toApi(c);
});

router.put('/contacts/:id', async (p, body) => {
  const getR = await fetch(`${DB}/contacts/${p.id}`);
  if (!getR.ok) return [404, { error: 'not found' }];
  const existing = await getR.json();
  const payload = {
    contactManagementName: body.name !== undefined ? body.name : existing.contactManagementName,
    phone: body.phone !== undefined ? body.phone : existing.phone,
    email: body.email !== undefined ? body.email : existing.email,
    address: body.address !== undefined ? body.address : existing.address,
    birthday: body.birthday !== undefined ? body.birthday : existing.birthday
  };
  const upd = await fetch(`${DB}/contacts/${p.id}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  });
  if (!upd.ok) return [upd.status, await upd.json()];
  const updated = await upd.json();
  return toApi(updated);
});

router.delete('/contacts/:id', async (p) => {
  const r = await fetch(`${DB}/contacts/${p.id}`, { method: 'DELETE' });
  if (!r.ok) return [404, { error: 'not found' }];
  return [204, null];
});
